import { Component, input, output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApIconComponent } from '../ap-icon/ap-icon.component';

@Component({
  selector: 'ap-button-custom',
  imports: [CommonModule, ApIconComponent],
  templateUrl: './ap-button-custom.component.html',
  styleUrl: './ap-button-custom.component.css',
})
export class ApButtonCustomComponent {
  label = input<string>('');
  icon = input<string>('');
  iconPos = input<'left' | 'right'>('left');
  /** 顯示的色碼 */
  colorCode = input<string>('#000000');
  disabled = input<boolean>(false);
  loading = input<boolean>(false);
  link = input<boolean>(false);
  type = input<'button' | 'submit' | 'reset'>('button');
  size = input<'mini' | 'small' | 'medium' | 'large'>('medium');
  rounded = input<boolean>(false);
  raised = input<boolean>(false);
  text = input<boolean>(false);
  outlined = input<boolean>(false);

  /** 受到Disable保護的Click */
  clicked = output<Event>();

  get buttonClasses(): string {
    const classes: string[] = [
      'inline-flex',
      'items-center',
      'justify-center',
      'gap-2',
      'font-semibold',
      'border',
      'outline-none',
      'px-2',
      'py-2',
    ];

    // Size classes
    if (this.size() === 'mini') {
      classes.push('text-xs');
    } else if (this.size() === 'small') {
      classes.push('text-base');
    } else if (this.size() === 'large') {
      classes.push('text-lg');
    } else {
      classes.push('text-md');
    }

    // Rounded/Icon-only variants
    const isIconOnly = this.isIconOnly;

    if (isIconOnly) {
      classes.length = 0;
      classes.push(
        'inline-flex',
        'items-center',
        'justify-center',
        this.rounded() ? 'rounded-full' : 'rounded-md',
        'border',
        'aspect-square',
      );

      if (this.size() === 'mini') {
        classes.push('w-6', 'h-6');
      } else if (this.size() === 'small') {
        classes.push('w-8', 'h-8');
      } else if (this.size() === 'large') {
        classes.push('w-12', 'h-12');
      } else {
        classes.push('w-10', 'h-10');
      }
    } else if (this.rounded()) {
      classes.push('rounded-full');
    } else {
      classes.push('rounded-md');
    }

    if (this.text()) {
      classes.push('bg-transparent', 'border-transparent', 'ap-btn-variant-text');
    } else if (this.outlined()) {
      classes.push('bg-transparent', 'ap-btn-variant-outlined');
    } else {
      classes.push('ap-btn-variant-filled');
      if (this.raised()) {
        classes.push('shadow-lg');
      }
    }

    if (this.disabled() || this.loading()) {
      classes.push('opacity-60', 'cursor-not-allowed');
    } else {
      classes.push('cursor-pointer');
    }

    return classes.join(' ');
  }

  get buttonStyle(): Record<string, string> {
    const color = this.colorCode();
    const vars: Record<string, string> = {
      '--ap-btn-color': color,
      '--ap-btn-color-hover': this.adjustColorBrightness(color, 0.15),
      '--ap-btn-color-active': this.adjustColorBrightness(color, -0.15),
    };

    return vars;
  }

  /** amount: -1~1，正值提高亮度、負值降低亮度 */
  private adjustColorBrightness(hex: string, amount: number): string {
    const normalized = hex.replace('#', '');
    const full =
      normalized.length === 3
        ? normalized
            .split('')
            .map((c) => c + c)
            .join('')
        : normalized;
    const bigint = parseInt(full, 16);
    if (Number.isNaN(bigint)) {
      return hex;
    }

    const r = (bigint >> 16) & 255;
    const g = (bigint >> 8) & 255;
    const b = bigint & 255;

    const adjust = (channel: number) =>
      amount >= 0
        ? channel + (255 - channel) * amount
        : channel * (1 + amount);

    const toHex = (channel: number) =>
      Math.round(Math.max(0, Math.min(255, adjust(channel))))
        .toString(16)
        .padStart(2, '0');

    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  }

  get iconSizeClass(): string {
    if (this.size() === 'large') return 'size-7';
    if (this.size() === 'mini') return 'size-3';
    return 'size-5';
  }

  get isIconOnly(): boolean {
    return !!this.icon() && !this.label();
  }

  handleClick(event: Event): void {
    if (!this.disabled() && !this.loading()) {
      this.clicked.emit(event);
    }
  }
}
